public static <A> ExecuteBiEntityActionServerPacket<A> decode(FriendlyByteBuf buf) {
    int otherEntityId = buf.readInt();
    boolean isOtherEntityTarget = buf.readBoolean();
    A entityAction = (A) Services.ACTION.entityDataType().receive(buf);
    return new ExecuteBiEntityActionServerPacket<>(otherEntityId, isOtherEntityTarget, entityAction);
}

@Override
public void handle(MinecraftServer server, ServerPlayer player) {
    server.execute(() -> Services.ACTION.executeEntity(entityAction, player));
}

@Override
public void execute(SerializableData.Instance data, Entity entity) {
    if (entity.level().isClientSide && entity instanceof LocalPlayer && data.get("side") == Side.SERVER) {
        Services.PLATFORM.sendC2S(new ExecuteEntityActionServerPacket<>(data.get("action")));
    } else if (!entity.level().isClientSide && data.get("side") == Side.CLIENT) {
        Services.PLATFORM.sendS2CTrackingAndSelf(new ExecuteEntityActionClientPacket<>(entity.getId(), data.get("action")), entity);
    }
}

@Override
public void execute(SerializableData.Instance data, Tuple<Entity, Entity> pair) {
    if (pair.getA().level().isClientSide && pair.getB().level().isClientSide && (pair.getA() instanceof LocalPlayer || pair.getB() instanceof LocalPlayer) && data.get("side") == Side.SERVER) {
        Services.PLATFORM.sendC2S(new ExecuteBiEntityActionServerPacket<>(pair.getA() instanceof LocalPlayer ? pair.getB().getId() : pair.getA().getId(), !(pair.getB() instanceof LocalPlayer), data.get("action")));
    } else if (!pair.getA().level().isClientSide && !pair.getB().level().isClientSide && data.get("side") == Side.CLIENT) {
        Services.PLATFORM.sendS2CTrackingAndSelf(new ExecuteBiEntityActionClientPacket<>(pair.getA().getId(), pair.getB().getId(), data.get("action")), pair.getA());
    }
}

