@Override
public void tick() {
    if (!entity.isAlive()) return;
    if (framesOnGround > 4) {
        ApugliPowers.BUNNY_HOP.get().reset(this, entity);
    }
    if (!ApugliPowers.BUNNY_HOP.get().canGainResource(entity)) {
        if (framesOnGround <= 4) {
            framesOnGround += 1;
        }
    } else {
        this.framesOnGround = 0;
    }
}

