default void reset(P power, LivingEntity entity) {
    if (getValue(power, entity) != 0) {
        assign(power, entity, 0);
        sync(entity, power);
    }
}

default void onTravel(LivingEntity entity, Vec3 movementInput) {
    if (!canGainResource(entity)) return;
    Services.POWER.getPowers(entity, this).forEach(power -> {
        SerializableData.Instance data = getDataFromPower(power);
        int tickRate = Math.max(1, data.getInt("tick_rate"));
        if(!entity.level().isClientSide && entity.tickCount % tickRate == 0) {
            int value = getValue(power, entity);
            if(increment(power, entity) != value) {
                sync(entity, power);
            }
        }
        entity.moveRelative(data.getFloat("increase_per_tick") * getValue(power, entity), movementInput);
    });
}

default boolean canGainResource(LivingEntity entity) {
    return !(entity.onGround() || entity.isInWater() || entity.isInLava() || entity.isPassenger() || entity.isFallFlying());
}

@Inject(method = "travel", at = @At("HEAD"))
private void apugli$travelLivingEntity(Vec3 movementInput, CallbackInfo ci) {
    if (this.isDeadOrDying() || this.level().isClientSide) return;
    ApugliPowers.BUNNY_HOP.get().onTravel((LivingEntity)(Object)this, movementInput);
}

